int pitch(const V& c){const int open[7]={0,64,59,55,50,45,40};return open[n(f(c,"string"))]+static_cast<int>(n(f(c,"fret")));}
int notePc(const V& note){const auto& s=note.string();const std::string letters="C D EF G A B";int pc=static_cast<int>(letters.find(s.front()));need(pc>=0&&pc<12,"SOURCE_NOTE_SPELLING");for(std::size_t i=1;i<s.size();++i)pc+=s[i]=='#'?1:s[i]=='b'?-1:0;return (pc%12+12)%12;}
bool contactPitch(const V& c){return c.isObject()&&f(c,"string").isNumber()&&f(c,"fret").isNumber()&&f(c,"note_name").isString()&&pitch(c)%12==notePc(f(c,"note_name"));}
