 if(c.find("chosen_articulations_per_bar")){const auto& a=f(c,"chosen_articulations_per_bar").array();for(std::size_t i=0;i<a.size();++i)if(n(f(a[i],"bar"))!=static_cast<std::int64_t>(i+1))return false;}
 if(c.find("chosen_harmonic_minor_pickups")){const auto& a=f(c,"chosen_harmonic_minor_pickups").array();const auto& domain=f(f(row.program,"source_rules"),"pickup_contact_domain").array();for(std::size_t i=0;i<a.size();++i){if(n(f(a[i],"bar"))!=static_cast<std::int64_t>(i+1)||n(f(a[i],"before_source_event_order"))!=static_cast<std::int64_t>(i*4+1))return false;if(std::find(domain.begin(),domain.end(),f(a[i],"contact"))==domain.end())return false;}}
