  const auto& es=f(f(row.original,"implementation"),"events").array();for(std::size_t j=0;j<strokes.size();++j){const auto& system=systems[j/block];if(system==V("alternate")||system==V("crosspick")){const V want=(f(c,"chosen_pick_start")==V("D"))!=(j%2!=0)?V("D"):V("U");if(strokes[j]!=want)return false;}else if(system==V("hybrid")){if(j%4==0){bool finger=false,pick=false;for(std::size_t z=j;z<j+4;++z){finger=finger||strokes[z]==V("m")||strokes[z]==V("a");pick=pick||strokes[z]==V("D")||strokes[z]==V("U");}if(!finger||!pick)return false;}}else {if(strokes[j]!=V("D")&&strokes[j]!=V("U"))return false;if(j%4){const auto prior=n(f(es[j-1],"string")),current=n(f(es[j],"string"));if(current!=prior&&strokes[j]!=(current<prior?V("D"):V("U")))return false;}if(system==V("sweep_burst")&&j%4&&strokes[j]!=strokes[j-1])return false;}}
